{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-b6d6223e2c403611","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Compute AI implementability scores from individual signal values.\n3\t\n4\tReads the epic's signal set from frontmatter and writes ai_implementability\n5\t+ ai_implementability_score back. Implementation epics use ai_signals (summed\n6\tagainst the thresholds below); Investigation epics use investigation_signals\n7\t(a routing model with guards — see classify_investigation).\n8\t\n9\tImplementation thresholds:\n10\t    score >= 3  → High\n11\t    0 <= score <= 2 → Medium\n12\t    score <= -1 → Low\n13\t\n14\tUsage:\n15\t    python3 scripts/compute_ai_scores.py RHAISTRAT-1234 RHAISTRAT-1235\n16\t    python3 scripts/compute_ai_scores.py --all\n17\t\"\"\"\n18\t\n19\timport glob\n20\timport os\n21\timport sys\n22\t\n23\tsys.path.insert(0, os.path.dirname(__file__))\n24\tfrom artifact_utils import read_frontmatter, update_frontmatter\n25\t\n26\tSIGNAL_FIELDS = [\n27\t    \"change_specificity\",\n28\t    \"pattern_precedent\",\n29\t    \"adapter_pattern\",\n30\t    \"existing_foundation\",\n31\t    \"open_questions\",\n32\t    \"external_dependency\",\n33\t    \"human_process_gates\",\n34\t    \"repo_access\",\n35\t    \"architecture_claims\",\n36\t]\n37\t\n38\t# Investigation epics use a separate, purpose-built signal set (see\n39\t# artifact_utils epic-task schema). It predicts, at decomposition time,\n40\t# whether the AI skill can resolve the unknowns or a person should.\n41\tINVESTIGATION_SIGNAL_FIELDS = [\n42\t    \"question_specificity\",\n43\t    \"source_accessibility\",\n44\t    \"local_runnability\",\n45\t    \"cluster_hardware_dependence\",\n46\t    \"human_judgment_required\",\n47\t]\n48\t\n49\t\n50\tdef classify(score):\n51\t    if score >= 3:\n52\t        return \"High\"\n53\t    elif score >= 0:\n54\t        return \"Medium\"\n55\t    else:\n56\t        return \"Low\"\n57\t\n58\t\n59\tdef classify_investigation(signals):\n60\t    \"\"\"Routing classification for Investigation epics.\n61\t\n62\t    Returns (score, classification). The class is a routing decision\n63\t    (High = assign to the AI skill, Medium = hybrid: skill does the desk/\n64\t    local parts and hands off the rest, Low = assign to a person), NOT a\n65\t    pure function of the score — two guards override the sum:\n66\t\n67\t      - Low guard: the skill can't meaningfully proceed — questions are too\n68\t        vague (question_specificity < 0), OR there is no AI-reachable oracle\n69\t        (nothing readable that *contains* the answer AND nothing runnable),\n70\t        OR the blockers drag the net negative.\n71\t      - High gate: only when nothing must be handed to a cluster or a human\n72\t        (both blockers == 0); any blocker caps the routing at Medium.\n73\t    \"\"\"\n74\t    s = {f: (signals.get(f) or 0) for f in INVESTIGATION_SIGNAL_FIELDS}\n75\t    total = sum(s.values())\n76\t    spec = s[\"question_specificity\"]\n77\t    src = s[\"source_accessibility\"]\n78\t    run = s[\"local_runnability\"]\n79\t    cluster = s[\"cluster_hardware_dependence\"]\n80\t    human = s[\"human_judgment_required\"]\n81\t\n82\t    if spec < 0 or (src <= 0 and run <= 0) or total <= -1:\n83\t        return total, \"Low\"\n84\t    if total >= 2 and cluster == 0 and human == 0:\n85\t        return total, \"High\"\n86\t    return total, \"Medium\"\n87\t\n88\t\n89\tdef compute_for_epic(epic_path):\n90\t    \"\"\"Compute and write score for a single epic file.\n91\t\n92\t    Returns (epic_id, score, classification) on success, or None if\n93\t    the epic has no ai_signals.\n94\t    \"\"\"\n95\t    data, _ = read_frontmatter(epic_path)\n96\t    if not data:\n97\t        return None\n98\t\n99\t    # Dispatch on the epic type, not on which signal block happens to be\n100\t    # present — an epic carrying a stale/duplicated block must still be scored\n101\t    # by its declared type's rubric. Investigation -> routing model; everything\n102\t    # else -> Implementation signal sum.\n103\t    if data.get(\"type\") == \"Investigation\":\n104\t        inv = data.get(\"investigation_signals\")\n105\t        if not isinstance(inv, dict):\n106\t            return None\n107\t        total, classification = classify_investigation(inv)\n108\t    else:\n109\t        signals = data.get(\"ai_signals\")\n110\t        if not signals or not isinstance(signals, dict):\n111\t            return None\n112\t\n113\t        total = 0\n114\t        for field in SIGNAL_FIELDS:\n115\t            val = signals.get(field, 0)\n116\t            if val is None:\n117\t                val = 0\n118\t            total += val\n119\t\n120\t        classification = classify(total)\n121\t\n122\t    epic_id = data.get(\"epic_id\", os.path.basename(epic_path))\n123\t\n124\t    old_score = data.get(\"ai_implementability_score\")\n125\t    old_class = data.get(\"ai_implementability\")\n126\t\n127\t    if old_score != total or old_class != classification:\n128\t        update_frontmatter(epic_path, {\n129\t            \"ai_implementability_score\": total,\n130\t            \"ai_implementability\": classification,\n131\t        }, \"epic-task\")\n132\t        changed = \" (updated)\"\n133\t    else:\n134\t        changed = \"\"\n135\t\n136\t    return epic_id, total, classification, changed\n137\t\n138\t\n139\tdef compute_for_strategy(strat_id):\n140\t    \"\"\"Compute scores for all epics of a strategy. Returns count of epics processed.\"\"\"\n141\t    # Two explicit patterns: conditional decompositions name their epics\n142\t    # {strat_id}-BRANCH-<X>-E00N.md, which {strat_id}-E*.md cannot match — the\n143\t    # 2026-08-19 eval's case-007 shipped 7 of 8 epics unscored because of it.\n144\t    # (Not {strat_id}*-E*.md: that would cross-match longer strategy ids\n145\t    # sharing the prefix.)\n146\t    epic_files = sorted(\n147\t        glob.glob(f\"artifacts/epic-tasks/{strat_id}-E*.md\")\n148\t        + glob.glob(f\"artifacts/epic-tasks/{strat_id}-BRANCH-*-E*.md\"))\n149\t\n150\t    if not epic_files:\n151\t        print(f\"  {strat_id}: no epic files found\", file=sys.stderr)\n152\t        return 0\n153\t\n154\t    count = 0\n155\t    for path in epic_files:\n156\t        result = compute_for_epic(path)\n157\t        if result:\n158\t            epic_id, score, classification, changed = result\n159\t            print(f\"  {epic_id}: {score} ({classification}){changed}\",\n160\t                  file=sys.stderr)\n161\t            count += 1\n162\t        else:\n163\t            print(f\"  {os.path.basename(path)}: no signals, skipped\",\n164\t                  file=sys.stderr)\n165\t\n166\t    return count\n167\t\n168\t\n169\tdef main():\n170\t    if len(sys.argv) < 2:\n171\t        print(\"Usage: compute_ai_scores.py [--all | STRAT-ID ...]\",\n172\t              file=sys.stderr)\n173\t        sys.exit(1)\n174\t\n175\t    if sys.argv[1] == \"--all\":\n176\t        epic_files = sorted(glob.glob(\"artifacts/epic-tasks/*-E*.md\"))\n177\t        strat_ids = set()\n178\t        for path in epic_files:\n179\t            basename = os.path.basename(path)\n180\t            parts = basename.rsplit(\"-E\", 1)\n181\t            if len(parts) == 2:\n182\t                strat_ids.add(parts[0])\n183\t        strat_ids = sorted(strat_ids)\n184\t    else:\n185\t        strat_ids = sys.argv[1:]\n186\t\n187\t    total = 0\n188\t    for strat_id in strat_ids:\n189\t        print(f\"Computing scores for {strat_id}:\", file=sys.stderr)\n190\t        total += compute_for_strategy(strat_id)\n191\t\n192\t    print(f\"Computed scores for {total} epics across \"\n193\t          f\"{len(strat_ids)} strategies\", file=sys.stderr)\n194\t\n195\t\n196\tif __name__ == \"__main__\":\n197\t    main()\n198\t"}]},"parent_tool_use_id":"chatcmpl-tool-871b8a555f0b9529","agent_id":"a7de8b91c40c6b063","session_id":"29cb84a9-828d-4dcd-a97c-1ceca07010da","uuid":"4d22a77e-e5fe-484d-8f86-deac262d98e6","t